contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address target, bytes memory data, uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount, "insufficient balance");
        uint cBalBefore = address(c).balance;
        uint testBalBefore = address(this).balance;
        bool reverted;
        c.Command{value: amount}(target, data); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
        uint cBalAfter = address(c).balance;
        uint testBalAfter = address(this).balance;
        bool isOwner = (c.Owner() == address(this));

        assert(isOwner ? (cBalAfter >= cBalBefore && testBalAfter <= testBalBefore) : reverted);
    }

    receive() external payable {}
}

